package main

import (
 "encoding/csv"
 "fmt"
 "io"
 "os"
 "path/filepath"
 "regexp"
 "strings"
)
type row map[string]string
func read(p string)([]row,error){f,e:=os.Open(p);if e!=nil{return nil,e};defer f.Close();r:=csv.NewReader(f);r.FieldsPerRecord=-1;h,e:=r.Read();if e!=nil{return nil,e};out:=[]row{};for{v,e:=r.Read();if e==io.EOF{break};if e!=nil{return nil,e};x:=row{};for i,k:=range h{if i<len(v){x[k]=v[i]}};out=append(out,x)};return out,nil}
func write(p string,h []string,rs [][]string)error{if e:=os.MkdirAll(filepath.Dir(p),0755);e!=nil{return e};f,e:=os.Create(p);if e!=nil{return e};defer f.Close();w:=csv.NewWriter(f);if e=w.Write(h);e!=nil{return e};for _,r:=range rs{if e=w.Write(r);e!=nil{return e}};w.Flush();return w.Error()}
func main(){if len(os.Args)<3{panic("usage: normalize-real-ts <input> <output")};in,out:=os.Args[1],os.Args[2];sy,_:=read(filepath.Join(in,"02_symbol_catalog.csv"));sm:=map[string]string{};for _,x:=range sy{sm[x["language"]+"\x00"+x["symbol"]]=x["symbol_id"]};ents,e:=read(filepath.Join(in,"08_parse_entries.csv"));if e!=nil{panic(e)};acts,e:=read(filepath.Join(in,"09_parse_actions.csv"));if e!=nil{panic(e)};dis:=[][]string{};for _,x:=range ents{k:=x["entry_kind"];if k!="STATE"&&k!="ACTION"{k="ERROR"};ns,al:="","";if k=="STATE"{ns=x["entry_ref"]}else{al=x["entry_ref"]};dis=append(dis,[]string{x["language"],x["parse_state"],sm[x["language"]+"\x00"+x["symbol"]],x["symbol"],"",k,ns,al})};if e=write(filepath.Join(out,"parse_dispatch.csv"),[]string{"language","parse_state","symbol_id","symbol_name","symbol_kind","dispatch_kind","next_state","action_list_id"},dis);e!=nil{panic(e)};al:=[][]string{};reduces:=0;for _,x:=range acts{a:=strings.Split(x["action_args"],",");for i:=range a{a[i]=strings.TrimSpace(a[i])};lhs,cc,dp,pid:="","","","";if x["action_kind"]=="REDUCE"{reduces++;if len(a)>0{lhs=sm[x["language"]+"\x00"+a[0]]};if len(a)>1{cc=a[1]};if len(a)>2{dp=a[2]};if len(a)>3{pid=a[3]}};al=append(al,[]string{x["language"],x["action_ref"],x["action_ordinal"],x["entry_count"],x["reusable"],x["action_kind"],first(a),"",lhs,"",cc,dp,pid})};if e=write(filepath.Join(out,"parse_action_lists.csv"),[]string{"language","action_list_id","action_ordinal","action_count","reusable","action_kind","target_state","extra","lhs_symbol_id","lhs_symbol_name","child_count","dynamic_precedence","production_id"},al);e!=nil{panic(e)};lex,_:=read(filepath.Join(in,"06_lex_transitions.csv"));acc,_:=read(filepath.Join(in,"07_lex_accepts.csv"));pair:=regexp.MustCompile(`'((?:\\.|[^'])*)'\s*,\s*(\d+)`);ld:=[][]string{};raw,dec:=0,0;for _,x:=range lex{m:=pair.FindAllStringSubmatch(x["guard"],-1);if len(m)==0{raw++;ld=append(ld,[]string{x["language"],x["lex_state"],"0","OPAQUE","","","false",fmt.Sprint(x["transition_kind"]=="EOF"),x["target_lex_state"],fmt.Sprint(x["transition_kind"]=="SKIP"),"","",fmt.Sprint(x["transition_kind"]=="IMMEDIATE")})}else{dec+=len(m);for _,z:=range m{ld=append(ld,[]string{x["language"],x["lex_state"],"0","CHAR",z[1],z[1],"false",fmt.Sprint(x["transition_kind"]=="EOF"),z[2],fmt.Sprint(x["transition_kind"]=="SKIP"),"","",fmt.Sprint(x["transition_kind"]=="IMMEDIATE")})}}};for _,x:=range acc{ld=append(ld,[]string{x["language"],x["lex_state"],"0","ACCEPT",x["token_symbol"],"","false","false","","false",sm[x["language"]+"\x00"+x["token_symbol"]],x["token_symbol"],"false"})};write(filepath.Join(out,"lex_dispatch.csv"),[]string{"language","lex_state","priority","predicate_kind","range_start","range_end","negated","eof","next_state","skip","accept_symbol_id","accept_symbol_name","immediate"},ld);fmt.Printf("PARSE_DISPATCH_ROWS=%d\nACTION_LISTS=%d\nRAW_ACTIONS=%d\nREDUCE_ROWS_WITH_LHS=%d\nLEX_DISPATCH_ROWS=%d\nLEX_GUARDS_RAW=%d\nLEX_GUARDS_DECODED=%d\nUNDECODED_LEX_GUARDS=%d\n",len(dis),len(al),len(acts),reduces,len(ld),raw,dec,raw)}
func first(a []string)string{if len(a)>0{return a[0]};return ""}
